return $input.all().map(item => {
  const data = item.json;

  // Erwartete Ports aus der Data Table
  const expected = (data.expected_ports || '')
    .split(',')
    .map(p => Number(p.trim()))
    .filter(p => p > 0);

  // Tatsächlich von Shodan erkannte Ports
  const observed = data.ports || [];

  // Vergleich
  const missing = expected.filter(p => !observed.includes(p));
  const unexpected = observed.filter(p => !expected.includes(p));

  return {
    json: {
      name: data.name,
      ip: data.ip,
      environment: data.environment,

      expected_ports: expected,
      observed_ports: observed,

      missing_ports: missing,
      unexpected_ports: unexpected,

      vulnerabilities: data.vulns || [],

      security_status:
        unexpected.length > 0 ? 'WARNING' :
        missing.length > 0 ? 'NOTICE' :
        'OK'
    }
  };
});

const results = [];

for (const item of $input.all()) {
  const data = item.json;

  for (const cve of data.vulnerabilities || []) {
    results.push({
      json: {
        name: data.name,
        ip: data.ip,
        environment: data.environment,

        cve: typeof cve === 'string'
          ? cve
          : cve.cve,

        // Nmap-Daten für die spätere Korrelation
        open_ports: data.open_ports || [],
        nmap_ports: data.nmap_ports || [],

        test_mode: false
      }
    });
  }
}

return results;

return $input.all().map(item => {
  const d = item.json;

  const cvss = Number(d.cvss_v3 ?? d.cvss ?? 0);
  const epss = Number(d.epss ?? 0);
  const kev = d.kev === true;

  let risk = 'LOW';

  if (kev || cvss >= 9) {
    risk = 'CRITICAL';
  } else if (cvss >= 7) {
    risk = 'HIGH';
  } else if (cvss >= 4) {
    risk = 'MEDIUM';
  }

  return {
    json: {
      asset: d.name,
      ip: d.ip,
      environment: d.environment,

      cve: d.cve_id,
      description: d.summary,

      cvss,
      epss,
      kev,
      risk,

      ransomware: d.ransomware_campaign || null,
      test_mode: d.test_mode === true,

      // Netzwerkdaten für die spätere CVE-Korrelation
      open_ports: d.open_ports || [],
      nmap_ports: d.nmap_ports || [],

      // Weitere Asset-Informationen erhalten
      observed_ports: d.observed_ports || [],
      expected_ports: d.expected_ports || []
    }
  };
});

const grouped = {};

for (const item of $input.all()) {
  const d = item.json;
  const key = d.ip;

  if (!key) continue;

  if (!grouped[key]) {
    grouped[key] = {
      name: d.asset || d.name,
      ip: d.ip,
      environment: d.environment,
      vulnerabilities: []
    };
  }

  const correlation = d.cve_correlation || {};
  const status = correlation.status || 'NO_CORRELATION_DATA';

  grouped[key].vulnerabilities.push({
    cve: d.cve,
    cvss: d.cvss,
    epss: d.epss,
    kev: d.kev,
    risk_hint: d.risk,
    description: d.description,
    ransomware: d.ransomware,

    // Vollständige Korrelationsdaten übernehmen
    cve_correlation: {
      ...correlation,
      status
    }
  });
}

// Pro Asset die CVE-Kategorien zählen
return Object.values(grouped).map(asset => {
  const vulns = asset.vulnerabilities;

  const countStatus = status =>
    vulns.filter(v =>
      v.cve_correlation.status === status
    ).length;

  const possibleCves = vulns.filter(v =>
    [
      'CPE_VERSION_MATCH',
      'PRODUCT_MATCH_VERSION_UNKNOWN',
      'RELATED_PRODUCT_REVIEW'
    ].includes(v.cve_correlation.status)
  );

  const relatedReviews = countStatus('RELATED_PRODUCT_REVIEW');

  const versionUnknown = countStatus(
    'PRODUCT_MATCH_VERSION_UNKNOWN'
  );

  const versionMatches = countStatus('CPE_VERSION_MATCH');

  const unmatchedCves = countStatus('PRODUCT_NOT_OBSERVED');

  const notAffected = countStatus('VERSION_NOT_AFFECTED');

  const noNvdData = countStatus('NO_NVD_DATA');

  return {
    json: {
      ...asset,

      cve_summary: {
        total_cves: vulns.length,

        possible_cves: possibleCves.length,

        cpe_version_matches: versionMatches,

        related_product_reviews: relatedReviews,

        version_unknown: versionUnknown,

        unmatched_cves: unmatchedCves,

        not_affected: notAffected,

        no_nvd_data: noNvdData,

        // Noch keine bestätigten Schwachstellen
        confirmed_cves: 0
      }
    }
  };
});

return $input.all().map(item => {
  const d = item.json;

  // CVE-Zusammenfassung aus Aggregate CVE Findings
  const cve = d.cve_summary || {};

  const totalCves = cve.total_cves || 0;
  const possibleCves = cve.possible_cves || 0;
  const relatedReviews = cve.related_product_reviews || 0;
  const versionUnknown = cve.version_unknown || 0;
  const unmatchedCves = cve.unmatched_cves || 0;
  const notAffected = cve.not_affected || 0;
  const noNvdData = cve.no_nvd_data || 0;

  // KEV-Kandidaten nur bei möglicher Produktkorrelation zählen
  const vulnerabilities = d.vulnerabilities || [];

  const kevCandidates = vulnerabilities.filter(v =>
    v.kev === true &&
    [
      'CPE_VERSION_MATCH',
      'PRODUCT_MATCH_VERSION_UNKNOWN',
      'RELATED_PRODUCT_REVIEW'
    ].includes(v.cve_correlation?.status)
  ).length;

  // Netzwerkbefunde
  const networkFindings = d.network_findings || [];

  const unexpectedPorts = networkFindings.filter(
    f => f.type === 'UNEXPECTED_PORT'
  ).length;

  const networkWarning = d.network_risk === 'WARNING';

  const missingPorts = (d.missing_ports || []).length;

  // Gesamtrisiko
  let risk = 'LOW';

  if (kevCandidates > 0) {
    risk = 'HIGH';

  } else if (
    possibleCves > 0 &&
    vulnerabilities.some(v =>
      ['CRITICAL', 'HIGH'].includes(v.risk_hint) &&
      [
        'CPE_VERSION_MATCH',
        'PRODUCT_MATCH_VERSION_UNKNOWN',
        'RELATED_PRODUCT_REVIEW'
      ].includes(v.cve_correlation?.status)
    )
  ) {
    risk = 'HIGH';

  } else if (
    possibleCves > 0 ||
    unexpectedPorts > 0 ||
    networkWarning 
  ) {
    risk = 'MEDIUM';
  }

  return {
    json: {
      ...d,

      risk_summary: {
        overall: risk,

        total_cves: totalCves,
        potential_cves: possibleCves,

        cpe_version_matches: cve.cpe_version_matches || 0,
        related_product_reviews: relatedReviews,
        version_unknown: versionUnknown,

        kev_candidates: kevCandidates,
        unmatched_cves: unmatchedCves,
        not_affected: notAffected,
        no_nvd_data: noNvdData,

        confirmed_cves: 0,

        unexpected_ports: unexpectedPorts,
        missing_ports: missingPorts,
        network_risk: d.network_risk || 'UNKNOWN'
      }
    }
  };
});

const items = $input.all();
const assets = items.map(item => item.json);

// --------------------------------------------------
// Hilfsfunktionen
// --------------------------------------------------

const esc = value => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const number = value => Number(value) || 0;

const colors = {
  HIGH: '#dc2626',
  MEDIUM: '#d97706',
  LOW: '#16a34a',
  UNKNOWN: '#64748b'
};

const riskLabel = risk => ({
  HIGH: 'HOCH',
  MEDIUM: 'MITTEL',
  LOW: 'NIEDRIG'
}[risk] || 'UNBEKANNT');

const correlationLabel = status => ({
  CPE_VERSION_MATCH: 'Möglicher Versions-Treffer – prüfen',
  PRODUCT_MATCH_VERSION_UNKNOWN: 'Produkt erkannt – Version prüfen',
  RELATED_PRODUCT_REVIEW: 'Ähnliches Produkt – prüfen',
  VERSION_NOT_AFFECTED: 'Laut Versionsabgleich nicht betroffen',
  PRODUCT_NOT_OBSERVED: 'Produkt nicht nachgewiesen',
  NO_NVD_DATA: 'Keine NVD-Daten'
}[status] || status || 'Nicht bewertet');

const possibleStatuses = [
  'CPE_VERSION_MATCH',
  'PRODUCT_MATCH_VERSION_UNKNOWN',
  'RELATED_PRODUCT_REVIEW'
];

const formatDate = value => {
  if (!value) return 'Unbekannt';

  const date = new Date(value);

  return Number.isNaN(date.getTime())
    ? esc(value)
    : date.toLocaleString('de-DE', {
        dateStyle: 'medium',
        timeStyle: 'short'
      });
};

const pill = (value, background = '#f1f5f9', color = '#334155') => `
  <span style="
    display:inline-block;
    padding:5px 9px;
    margin:2px 3px 2px 0;
    border-radius:6px;
    background:${background};
    color:${color};
    font-size:12px;
    font-weight:600;">
    ${esc(value)}
  </span>
`;

const portList = (ports, emptyText = 'Keine') => {
  const unique = [...new Set((ports || []).map(Number))]
    .filter(Number.isFinite)
    .sort((a, b) => a - b);

  return unique.length
    ? unique.map(port => pill(port)).join('')
    : `<span style="color:#94a3b8;font-size:12px;">${emptyText}</span>`;
};

const metricCard = (value, label, color = '#0f172a', hint = '') => `
  <td width="25%" valign="top" style="padding:5px;">
    <table width="100%" cellpadding="0" cellspacing="0"
      style="background:#ffffff;border:1px solid #e2e8f0;border-radius:10px;">
      <tr>
        <td style="padding:15px;">
          <div style="font-size:26px;font-weight:700;color:${color};">
            ${value}
          </div>
          <div style="font-size:11px;color:#475569;margin-top:5px;">
            ${label}
          </div>
          ${hint ? `<div style="font-size:10px;color:#94a3b8;margin-top:4px;">${hint}</div>` : ''}
        </td>
      </tr>
    </table>
  </td>
`;

// --------------------------------------------------
// Gesamtauswertung
// --------------------------------------------------

const count = {
  assets: assets.length,

  high: assets.filter(a => a.risk_summary?.overall === 'HIGH').length,
  medium: assets.filter(a => a.risk_summary?.overall === 'MEDIUM').length,
  low: assets.filter(a => a.risk_summary?.overall === 'LOW').length,

  possibleCves: assets.reduce(
    (sum, a) => sum + number(a.risk_summary?.potential_cves), 0
  ),

  kev: assets.reduce(
    (sum, a) => sum + number(a.risk_summary?.kev_candidates), 0
  ),

  unexpectedPorts: assets.reduce(
    (sum, a) => sum + number(a.risk_summary?.unexpected_ports), 0
  ),

  confirmedCves: assets.reduce(
    (sum, a) => sum + number(a.risk_summary?.confirmed_cves), 0
  )
};

const generatedAt = new Date().toLocaleString('de-DE', {
  dateStyle: 'full',
  timeStyle: 'short'
});

const overallColor = count.high > 0
  ? colors.HIGH
  : count.medium > 0
    ? colors.MEDIUM
    : colors.LOW;

const overallText = count.high > 0
  ? 'Erhöhter Handlungsbedarf'
  : count.medium > 0
    ? 'Prüfbedarf vorhanden'
    : 'Keine erhöhten Risiken erkannt';

// --------------------------------------------------
// Asset-Übersicht
// --------------------------------------------------

const assetOverview = assets.map(asset => {
  const risk = asset.risk_summary?.overall || 'UNKNOWN';
  const summary = asset.risk_summary || {};
  const color = colors[risk] || colors.UNKNOWN;

  return `
    <tr>
      <td style="padding:13px 10px;border-bottom:1px solid #e2e8f0;">
        <strong style="color:#0f172a;">${esc(asset.name)}</strong>
        <div style="font-size:11px;color:#64748b;margin-top:4px;">
          ${esc(asset.ip)} · ${esc(asset.environment)}
        </div>
      </td>

      <td align="center" style="padding:10px;border-bottom:1px solid #e2e8f0;">
        <span style="background:${color};color:#fff;padding:6px 10px;
          border-radius:20px;font-size:10px;font-weight:bold;">
          ${riskLabel(risk)}
        </span>
      </td>

      <td align="center" style="padding:10px;border-bottom:1px solid #e2e8f0;
        color:#b45309;font-weight:bold;">
        ${number(summary.potential_cves)}
      </td>

      <td align="center" style="padding:10px;border-bottom:1px solid #e2e8f0;
        color:#dc2626;font-weight:bold;">
        ${number(summary.kev_candidates)}
      </td>

      <td align="center" style="padding:10px;border-bottom:1px solid #e2e8f0;
        color:#dc2626;font-weight:bold;">
        ${number(summary.unexpected_ports)}
      </td>
    </tr>
  `;
}).join('');

// --------------------------------------------------
// Asset-Detailkarten
// --------------------------------------------------

const assetDetails = assets.map(asset => {
  const risk = asset.risk_summary?.overall || 'UNKNOWN';
  const summary = asset.risk_summary || {};
  const cveSummary = asset.cve_summary || {};
  const riskColor = colors[risk] || colors.UNKNOWN;

  const expected = asset.expected_ports || [];
  const nmap = asset.nmap_ports || [];
  const shodan = asset.observed_ports || [];

  const comparison = asset.port_comparison || {};

  const unexpected = comparison.unexpected_nmap || [];
  const missing = comparison.missing_expected || [];
  const onlyNmap = comparison.only_nmap || [];
  const onlyShodan = comparison.only_shodan || [];
  const common = comparison.common || [];

  const vulnerabilities = asset.vulnerabilities || [];
  const findings = asset.network_findings || [];

  const unexpectedFindings = findings.filter(
    f => f.type === 'UNEXPECTED_PORT'
  );

  const informationalFindings = findings.filter(
    f => f.type !== 'UNEXPECTED_PORT'
  );

  const networkRisk = asset.network_risk || 'UNKNOWN';
  const networkColor = networkRisk === 'WARNING'
    ? colors.MEDIUM
    : networkRisk === 'OK'
      ? colors.LOW
      : colors.UNKNOWN;

  const cveRows = vulnerabilities.map(v => {
    const status = v.cve_correlation?.status;
    const possible = possibleStatuses.includes(status);

    const statusColor = possible ? '#b45309' : '#475569';
    const kevColor = v.kev === true ? '#dc2626' : '#64748b';

    return `
      <tr>
        <td valign="top" style="padding:13px 9px;border-bottom:1px solid #e2e8f0;">
          <a href="https://nvd.nist.gov/vuln/detail/${encodeURIComponent(v.cve || '')}"
            style="font-weight:bold;color:#2563eb;text-decoration:none;">
            ${esc(v.cve || 'Unbekannte CVE')}
          </a>

          <div style="font-size:11px;color:#64748b;margin-top:6px;">
            CVSS: <strong>${esc(v.cvss ?? '–')}</strong>
          </div>

          <div style="font-size:11px;color:${kevColor};margin-top:4px;font-weight:bold;">
            KEV: ${v.kev === true ? 'JA – im KEV-Katalog' : 'Nein'}
          </div>

          <div style="font-size:11px;color:#64748b;margin-top:4px;">
            Risiko-Hinweis: ${esc(v.risk_hint || 'Unbekannt')}
          </div>
        </td>

        <td valign="top" style="padding:13px 9px;border-bottom:1px solid #e2e8f0;">
          <div style="font-size:12px;font-weight:bold;color:${statusColor};">
            ${esc(correlationLabel(status))}
          </div>

          <div style="font-size:11px;color:#64748b;margin-top:7px;line-height:1.6;">
            ${esc(v.description || 'Keine Beschreibung verfügbar')}
          </div>
        </td>
      </tr>
    `;
  }).join('');

  const findingRows = unexpectedFindings.map(f => `
    <tr>
      <td style="padding:9px;border-bottom:1px solid #e2e8f0;">
        <strong>${esc(f.port)}</strong>
      </td>
      <td style="padding:9px;border-bottom:1px solid #e2e8f0;">
        ${esc(f.service || 'Unbekannt')}
      </td>
      <td style="padding:9px;border-bottom:1px solid #e2e8f0;color:#b45309;">
        ${esc(f.message || 'Unerwarteter Port')}
      </td>
    </tr>
  `).join('');

  const infoRows = informationalFindings.map(f => `
    <tr>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;">
        ${esc(f.type || 'INFO')}
      </td>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;color:#64748b;">
        ${esc(f.message || 'Keine weitere Beschreibung')}
      </td>
    </tr>
  `).join('');

  return `
    <table width="100%" cellpadding="0" cellspacing="0"
      style="margin-top:18px;background:#ffffff;border:1px solid #e2e8f0;
      border-radius:10px;">

      <!-- Asset-Kopf -->
      <tr>
        <td style="padding:19px 20px;background:#f8fafc;
          border-bottom:1px solid #e2e8f0;">

          <table width="100%" cellpadding="0" cellspacing="0">
            <tr>
              <td>
                <div style="font-size:17px;font-weight:bold;color:#0f172a;">
                  ${esc(asset.name)}
                </div>
                <div style="font-size:12px;color:#64748b;margin-top:5px;">
                  ${esc(asset.ip)} · ${esc(asset.environment)}
                </div>
              </td>

              <td align="right" valign="middle">
                <span style="display:inline-block;background:${riskColor};
                  color:#ffffff;padding:7px 11px;border-radius:20px;
                  font-size:11px;font-weight:bold;">
                  ${riskLabel(risk)}
                </span>
              </td>
            </tr>
          </table>

          <div style="margin-top:12px;font-size:11px;color:#64748b;">
            Netzwerkstatus:
            <strong style="color:${networkColor};">${esc(networkRisk)}</strong>
            · Scan:
            <strong>${asset.scan_success === true ? 'Erfolgreich' : 'Nicht erfolgreich / unbekannt'}</strong>
          </div>
        </td>
      </tr>

      <tr>
        <td style="padding:19px 20px;">

          <!-- CVE-Kennzahlen -->
          <div style="font-size:13px;font-weight:bold;color:#0f172a;margin-bottom:10px;">
            Sicherheitsanalyse
          </div>

          <table width="100%" cellpadding="0" cellspacing="0"
            style="background:#f8fafc;border-radius:8px;">
            <tr>
              <td width="25%" style="padding:11px 8px;">
                <div style="font-size:21px;font-weight:bold;color:#0f172a;">
                  ${number(summary.total_cves)}
                </div>
                <div style="font-size:10px;color:#64748b;">CVE-Hinweise</div>
              </td>

              <td width="25%" style="padding:11px 8px;">
                <div style="font-size:21px;font-weight:bold;color:#b45309;">
                  ${number(summary.potential_cves)}
                </div>
                <div style="font-size:10px;color:#64748b;">Mögliche Treffer</div>
              </td>

              <td width="25%" style="padding:11px 8px;">
                <div style="font-size:21px;font-weight:bold;color:#dc2626;">
                  ${number(summary.kev_candidates)}
                </div>
                <div style="font-size:10px;color:#64748b;">KEV-Kandidaten</div>
              </td>

              <td width="25%" style="padding:11px 8px;">
                <div style="font-size:21px;font-weight:bold;color:#16a34a;">
                  ${number(summary.confirmed_cves)}
                </div>
                <div style="font-size:10px;color:#64748b;">Bestätigt</div>
              </td>
            </tr>
          </table>

          <table width="100%" cellpadding="0" cellspacing="0"
            style="margin-top:9px;background:#f8fafc;border-radius:8px;">
            <tr>
              <td width="25%" style="padding:10px 8px;">
                <strong>${number(cveSummary.cpe_version_matches)}</strong>
                <div style="font-size:10px;color:#64748b;">Versions-Treffer</div>
              </td>
              <td width="25%" style="padding:10px 8px;">
                <strong>${number(cveSummary.related_product_reviews)}</strong>
                <div style="font-size:10px;color:#64748b;">Produkt-Prüfungen</div>
              </td>
              <td width="25%" style="padding:10px 8px;">
                <strong>${number(cveSummary.version_unknown)}</strong>
                <div style="font-size:10px;color:#64748b;">Version unbekannt</div>
              </td>
              <td width="25%" style="padding:10px 8px;">
                <strong>${number(cveSummary.unmatched_cves)}</strong>
                <div style="font-size:10px;color:#64748b;">Nicht korreliert</div>
              </td>
            </tr>
          </table>

          <div style="margin-top:9px;font-size:11px;color:#64748b;">
            Nicht betroffen: ${number(cveSummary.not_affected)}
            · Keine NVD-Daten: ${number(cveSummary.no_nvd_data)}
          </div>

          <!-- CVE-Details -->
          <div style="border-top:1px solid #e2e8f0;margin-top:19px;padding-top:16px;">
            <div style="font-size:13px;font-weight:bold;color:#0f172a;margin-bottom:10px;">
              CVE-Details
            </div>

            ${vulnerabilities.length ? `
              <table width="100%" cellpadding="0" cellspacing="0"
                style="border-collapse:collapse;font-size:12px;">
                <tr style="background:#f1f5f9;text-align:left;">
                  <th width="30%" style="padding:9px;">Schwachstelle</th>
                  <th style="padding:9px;">Korrelation und Beschreibung</th>
                </tr>
                ${cveRows}
              </table>
            ` : `
              <div style="padding:13px;background:#f0fdf4;border-radius:7px;
                font-size:12px;color:#166534;">
                Keine CVE-Hinweise für dieses Asset gefunden.
              </div>
            `}
          </div>

          <!-- Netzwerk -->
          <div style="border-top:1px solid #e2e8f0;margin-top:19px;padding-top:16px;">
            <div style="font-size:13px;font-weight:bold;color:#0f172a;margin-bottom:13px;">
              Netzwerk- und Portanalyse
            </div>

            <div style="font-size:11px;color:#64748b;margin-bottom:5px;">
              In der Asset-Konfiguration freigegeben
            </div>
            <div style="margin-bottom:12px;">
              ${portList(expected)}
            </div>

            <div style="font-size:11px;color:#64748b;margin-bottom:5px;">
              Durch Nmap gefunden
            </div>
            <div style="margin-bottom:12px;">
              ${portList(nmap)}
            </div>

            <div style="font-size:11px;color:#64748b;margin-bottom:5px;">
              Durch Shodan gefunden
            </div>
            <div style="margin-bottom:12px;">
              ${portList(shodan)}
            </div>

            <div style="font-size:11px;color:#64748b;margin-bottom:5px;">
              Von beiden Quellen gefunden
            </div>
            <div style="margin-bottom:12px;">
              ${portList(common)}
            </div>

            <div style="font-size:11px;color:#b91c1c;font-weight:bold;margin-bottom:5px;">
              Unerwartete Nmap-Ports
            </div>
            <div style="margin-bottom:12px;">
              ${unexpected.length
                ? unexpected.map(p => pill(p, '#fef2f2', '#b91c1c')).join('')
                : '<span style="font-size:12px;color:#16a34a;">Keine unerwarteten Ports</span>'}
            </div>

            <div style="font-size:11px;color:#b45309;font-weight:bold;margin-bottom:5px;">
              Erwartete, aber nicht gefundene Ports
            </div>
            <div style="margin-bottom:12px;">
              ${missing.length
