function parseCpe(cpe) {
  if (!cpe || typeof cpe !== 'string') return null;

  const parts = cpe.split(':');

  // CPE 2.3: cpe:2.3:a:vendor:product:version:...
  if (parts[1] === '2.3') {
    return {
      vendor: parts[3]?.toLowerCase(),
      product: parts[4]?.toLowerCase(),
      version: parts[5] || '*'
    };
  }

  // CPE 2.2: cpe:/a:vendor:product:version
  if (parts[1]?.startsWith('/')) {
    return {
      vendor: parts[2]?.toLowerCase(),
      product: parts[3]?.toLowerCase(),
      version: parts[4] || '*'
    };
  }

  return null;
}


// Sammelt vulnerable CPE-Einträge aus der NVD-Antwort.
// Achtung: AND / OR / negate werden hier noch nicht ausgewertet.
function collectCpeMatches(obj, result = []) {
  if (!obj || typeof obj !== 'object') return result;

  if (Array.isArray(obj)) {
    for (const entry of obj) {
      collectCpeMatches(entry, result);
    }
    return result;
  }

  if (Array.isArray(obj.cpeMatch)) {
    for (const match of obj.cpeMatch) {
      if (match.vulnerable === true) {
        result.push(match);
      }
    }
  }

  for (const value of Object.values(obj)) {
    if (value && typeof value === 'object') {
      collectCpeMatches(value, result);
    }
  }

  return result;
}


// Vergleicht einfache numerische Versionsnummern.
// Rückgabe: 1 = größer, -1 = kleiner, 0 = gleich, null = unbekannt.
function compareVersions(a, b) {
  if (!a || !b) return null;

  if (
    !/^\d+(\.\d+)*$/.test(String(a)) ||
    !/^\d+(\.\d+)*$/.test(String(b))
  ) {
    return null;
  }

  const aa = String(a).split('.').map(Number);
  const bb = String(b).split('.').map(Number);
  const length = Math.max(aa.length, bb.length);

  for (let i = 0; i < length; i++) {
    const x = aa[i] ?? 0;
    const y = bb[i] ?? 0;

    if (x > y) return 1;
    if (x < y) return -1;
  }

  return 0;
}


// Prüft, ob eine erkannte Version in den NVD-Versionsbereich fällt.
function versionAffected(version, match) {
  if (!version) return 'UNKNOWN';

  const criteria = parseCpe(match.criteria);
  if (!criteria) return 'UNKNOWN';

  const fixedVersion = criteria.version;

  // Exakte Version aus dem CPE
  if (fixedVersion && fixedVersion !== '*') {
    const comparison = compareVersions(version, fixedVersion);

    if (comparison === null) return 'UNKNOWN';

    return comparison === 0 ? 'AFFECTED' : 'NOT_AFFECTED';
  }

  // Untere Versionsgrenze
  if (match.versionStartIncluding) {
    const c = compareVersions(version, match.versionStartIncluding);

    if (c === null) return 'UNKNOWN';
    if (c < 0) return 'NOT_AFFECTED';
  }

  if (match.versionStartExcluding) {
    const c = compareVersions(version, match.versionStartExcluding);

    if (c === null) return 'UNKNOWN';
    if (c <= 0) return 'NOT_AFFECTED';
  }

  // Obere Versionsgrenze
  if (match.versionEndIncluding) {
    const c = compareVersions(version, match.versionEndIncluding);

    if (c === null) return 'UNKNOWN';
    if (c > 0) return 'NOT_AFFECTED';
  }

  if (match.versionEndExcluding) {
    const c = compareVersions(version, match.versionEndExcluding);

    if (c === null) return 'UNKNOWN';
    if (c >= 0) return 'NOT_AFFECTED';
  }

  return 'AFFECTED';
}


// Erkennt verwandte Produkte, ohne sie als identisch zu behandeln.
function isRelatedProduct(detected, criteria) {
  const vendor = (detected.vendor || '').toLowerCase();
  const product = (detected.product || '').toLowerCase();

  const nvdVendor = (criteria.vendor || '').toLowerCase();
  const nvdProduct = (criteria.product || '').toLowerCase();

  // OpenResty basiert auf nginx.
  // Das ist ein Prüfhinweis, kein bestätigter Produktmatch.
  if (
    vendor === 'openresty' &&
    product === 'ngx_openresty' &&
    (
      nvdProduct.includes('nginx') ||
      nvdVendor === 'igor_sysoev'
    )
  ) {
    return true;
  }

  return false;
}


return $input.all().map(item => {
  const d = item.json;

  const nvdCve = d.vulnerabilities?.[0]?.cve;
  const configurations = nvdCve?.configurations || [];

  const nvdMatches = collectCpeMatches(configurations);

  // Erkannte Software aus Nmap normalisieren
  const detected = (d.open_ports || []).flatMap(port => {
    const cpes = Array.isArray(port.cpe)
      ? port.cpe
      : port.cpe
        ? [port.cpe]
        : [];

    return cpes.map(cpe => {
      const parsed = parseCpe(cpe);

      return parsed ? {
        ...parsed,
        port: port.port,
        detectedProduct: port.product,
        detectedVersion: port.version
      } : null;
    }).filter(Boolean);
  });

  const findings = [];
  const relatedProducts = [];

  // Exakte Produktmatches prüfen
  for (const match of nvdMatches) {
    const criteria = parseCpe(match.criteria);

    if (!criteria) continue;

    const productMatches = detected.filter(found =>
      found.vendor === criteria.vendor &&
      found.product === criteria.product
    );

    for (const found of productMatches) {
      const version = found.detectedVersion ||
        (found.version !== '*' ? found.version : null);

      findings.push({
        vendor: criteria.vendor,
        product: criteria.product,
        detected_version: version,
        port: found.port,
        version_status: versionAffected(version, match)
      });
    }
  }

  // Verwandte Produkte separat erfassen
  for (const match of nvdMatches) {
    const criteria = parseCpe(match.criteria);

    if (!criteria) continue;

    const related = detected.filter(found =>
      isRelatedProduct(found, criteria)
    );

    for (const found of related) {
      relatedProducts.push({
        nvd_vendor: criteria.vendor,
        nvd_product: criteria.product,
        detected_vendor: found.vendor,
        detected_product: found.product,
        detected_version: found.detectedVersion,
        port: found.port,
        status: 'MANUAL_REVIEW_REQUIRED'
      });
    }
  }

  // Doppelte Hinweise vermeiden
  const uniqueRelatedProducts = [
    ...new Map(
      relatedProducts.map(entry => [
        `${entry.nvd_vendor}:${entry.nvd_product}:${entry.port}`,
        entry
      ])
    ).values()
  ];

  // Korrelationsstatus bestimmen
  let correlationStatus = 'PRODUCT_NOT_OBSERVED';

  if (!nvdCve) {
    correlationStatus = 'NO_NVD_DATA';

  } else if (
    findings.some(f => f.version_status === 'AFFECTED')
  ) {
    correlationStatus = 'CPE_VERSION_MATCH';

  } else if (
    findings.some(f => f.version_status === 'UNKNOWN')
  ) {
    correlationStatus = 'PRODUCT_MATCH_VERSION_UNKNOWN';

  } else if (
    findings.some(f => f.version_status === 'NOT_AFFECTED')
  ) {
    correlationStatus = 'VERSION_NOT_AFFECTED';

  } else if (uniqueRelatedProducts.length > 0) {
    correlationStatus = 'RELATED_PRODUCT_REVIEW';
  }

  return {
    json: {
      ...d,
      cve_correlation: {
        status: correlationStatus,
        detected_software: detected,
        findings,
        related_products: uniqueRelatedProducts,
        nvd_found: !!nvdCve
      }
    }
  };
});
